(() => {
'use strict';
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const ui={story:$('#story'),dialog:$('#dialogue'),speaker:$('#speaker'),line:$('#line'),choices:$('#choiceRow'),hint:$('#dialogHint'),battle:$('#battle'),mini:$('#minigame'),timing:$('#timing'),ending:$('#ending'),toast:$('#toast')};
let W=960,H=540,scaleX=1,scaleY=1,raf=0,toastTimer;
const game={started:false,room:'studio',x:170,y:380,dir:1,keys:{},dialog:null,dialogIndex:0,dialogueLock:false,viewers:12,stars:0,hp:20,maxhp:20,roomVisited:false,miniWon:false,bossWon:false,helpedDot:false,secret:false,choiceKind:'',battle:null,turn:1,defending:false,attackTimer:0,attackPos:0,attackDir:1,miniSequence:[],miniInput:[],miniBusy:false,movingTime:0};
const rooms={
 studio:{label:'STUDIO ZERO · CHANNEL 0',objects:[{id:'dot',x:.34,y:.60,r:.09},{id:'console',x:.72,y:.57,r:.085},{id:'portal',x:.91,y:.56,r:.1},{id:'secret',x:.12,y:.72,r:.07}]},
 channel:{label:'CHANNEL 9 · THE GAME-SHOW GRAVEYARD',objects:[{id:'host',x:.52,y:.55,r:.09},{id:'mite',x:.77,y:.58,r:.09},{id:'crate',x:.12,y:.72,r:.07},{id:'boss',x:.91,y:.56,r:.1}]}
};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function resize(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.floor(r.width*dpr);canvas.height=Math.floor(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);W=r.width;H=r.height;scaleX=W/960;scaleY=H/540;}
window.addEventListener('resize',resize);resize();
function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}}
function text(s,x,y,size,color='#fff',align='center',font='Space Grotesk'){ctx.fillStyle=color;ctx.font=`${size}px '${font}',sans-serif`;ctx.textAlign=align;ctx.fillText(s,x,y)}
function draw(){if(!game.started){raf=requestAnimationFrame(draw);return}ctx.save();ctx.scale(scaleX,scaleY);const t=performance.now()/1000;drawRoom(t);drawObjects(t);drawPlayer();drawVignette();ctx.restore();raf=requestAnimationFrame(draw)}
function drawRoom(t){const c=ctx;let grd=c.createLinearGradient(0,0,0,540);if(game.room==='studio'){grd.addColorStop(0,'#1c1738');grd.addColorStop(.64,'#211b3c');grd.addColorStop(.641,'#342b4c');grd.addColorStop(1,'#18152b')}else{grd.addColorStop(0,'#16182f');grd.addColorStop(.64,'#201e3d');grd.addColorStop(.641,'#363048');grd.addColorStop(1,'#171425')}c.fillStyle=grd;c.fillRect(0,0,960,540);
 // rear wall panels
 for(let x=0;x<960;x+=80){c.fillStyle=(x/80)%2?'#ffffff05':'#00000008';c.fillRect(x,0,78,342);c.strokeStyle='#a79ad018';c.lineWidth=1;c.strokeRect(x+5,35,68,244)}
 // floor checker
 for(let y=344;y<540;y+=32){for(let x=0;x<960;x+=48){c.fillStyle=((x/48+y/32)%2)?'#ffffff08':'#08071a12';c.fillRect(x,y,48,32)}}
 // rafters / lights
 c.fillStyle='#100d27';c.fillRect(0,0,960,25);for(let i=0;i<5;i++){let x=96+i*192;c.fillStyle='#322b4f';c.fillRect(x,24,8,66);c.fillStyle=i===2?'#ff4e9b':'#61e6da';c.shadowColor=c.fillStyle;c.shadowBlur=18;c.fillRect(x-18,83,44,4);c.shadowBlur=0}
 if(game.room==='studio'){
  // giant screen + curtains
  rounded(300,54,360,198,8,'#0a0919','#6d628d');rounded(310,64,340,178,4,'#100d25','#4c4368');c.fillStyle='#ff4e9b';c.fillRect(314,68,332,4);c.fillStyle='#61e6da';c.fillRect(314,232,332,4);
  text('TENNA TONIGHT',480,125,24,'#716886');text('NOW: 12 VIEWERS',480,159,12,'#ff4e9b','center','DM Mono');text('PLEASE DO NOT CHANGE THE CHANNEL',480,188,10,'#817897','center','DM Mono');
  for(let side of [0,1]){let x=side?750:50;c.fillStyle='#422349';c.beginPath();c.moveTo(x,25);c.lineTo(x+115,25);c.lineTo(x+88,335);c.lineTo(x+12,335);c.closePath();c.fill();for(let j=0;j<5;j++){c.fillStyle='#57294a';c.fillRect(x+j*20,26,8,300)}}
  // stage rug
  c.fillStyle='#734078';c.beginPath();c.ellipse(485,427,220,43,0,0,Math.PI*2);c.fill();c.strokeStyle='#f9b5d633';c.lineWidth=4;c.stroke();
  // desk
  rounded(620,273,158,76,8,'#2c2649','#6a5e87');c.fillStyle='#e14892';c.fillRect(635,286,128,4);text('ON AIR',699,318,13,'#fff','center','DM Mono');
 }else{
  // graveyard strange suspended tv stages
  for(let i=0;i<4;i++){let x=95+i*220,y=94+(i%2)*62;c.save();c.translate(x,y);c.rotate(Math.sin(t+i)*.025);rounded(-66,-45,132,90,8,'#080914','#6b5b80');rounded(-59,-38,118,76,3,['#3d2762','#234a58','#5c2747','#29365e'][i],'#9c84ad');text(['?','★','NO SIGNAL','LIVE'][i],0,6,16,'#f9d1ff','center','DM Mono');c.restore()}
  // curtains and hazard stripe
  c.fillStyle='#5b1d49';c.fillRect(0,0,35,350);c.fillRect(925,0,35,350);for(let x=0;x<960;x+=30){c.fillStyle=x%60?'#f4cc5d':'#221b30';c.fillRect(x,343,15,8)}
  // low mist
  c.globalAlpha=.12;for(let i=0;i<5;i++){c.fillStyle='#b4a1db';c.beginPath();c.ellipse(((t*20+i*230)%1200)-100,390+i*27,110,15,0,0,Math.PI*2);c.fill()}c.globalAlpha=1;
 }
 // vignette wall labels
 text(game.room==='studio'?'STUDIO 0': 'WORLD 9',480,518,10,'#a69ab8','center','DM Mono');
}
function sprite(x,y,type,scale=1,opts={}){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);const c=ctx;
 if(type==='tenna'){
  // ground shadow
  c.fillStyle='#0007';c.beginPath();c.ellipse(0,3,18,6,0,0,Math.PI*2);c.fill();
  c.fillStyle='#16122d';c.fillRect(-13,-3,10,9);c.fillRect(3,-3,10,9);c.fillStyle='#e9e2f2';c.fillRect(-13,-15,26,16);c.fillStyle='#f04b99';c.fillRect(-13,-14,26,4);c.fillStyle='#111025';c.fillRect(-9,-12,18,8);c.fillStyle='#67f4e3';c.fillRect(-6,-10,3,3);c.fillRect(4,-10,3,3);c.fillStyle='#d9d3e6';c.fillRect(-16,-32,32,19);c.fillStyle='#f4f0ff';c.fillRect(-12,-38,24,8);c.fillStyle='#23203a';c.fillRect(-17,-44,34,8);c.fillStyle='#ff4e9b';c.fillRect(-15,-46,30,4);c.fillStyle='#fff';c.fillRect(-12,-35,7,5);c.fillRect(5,-35,7,5);c.fillStyle='#1b1832';c.fillRect(-10,-34,3,4);c.fillRect(7,-34,3,4);c.fillStyle='#ff4e9b';c.fillRect(-2,-30,4,2);c.fillStyle='#f0d668';c.fillRect(0,-54,2,9);c.fillStyle='#ff4e9b';c.fillRect(-2,-57,6,5);
 }else if(type==='dot'){
  c.fillStyle='#0007';c.beginPath();c.ellipse(0,2,16,5,0,0,Math.PI*2);c.fill();c.fillStyle='#48426a';c.fillRect(-11,-22,22,22);c.fillStyle='#c9d5bd';c.fillRect(-10,-37,20,16);c.fillStyle='#edc7a0';c.fillRect(-8,-33,16,11);c.fillStyle='#24203a';c.fillRect(-8,-41,18,7);c.fillStyle='#ffcf70';c.fillRect(-5,-28,3,3);c.fillRect(4,-28,3,3);c.fillStyle='#8fd6d0';c.fillRect(-6,-21,12,3);
 }else if(type==='host'){
  c.fillStyle='#0008';c.beginPath();c.ellipse(0,2,20,5,0,0,Math.PI*2);c.fill();c.fillStyle='#492449';c.fillRect(-15,-26,30,26);c.fillStyle='#f4c8a9';c.fillRect(-12,-43,24,20);c.fillStyle='#1a162e';c.fillRect(-15,-47,30,8);c.fillStyle='#f6d374';c.fillRect(-7,-36,4,4);c.fillRect(4,-36,4,4);c.fillStyle='#ff4e9b';c.fillRect(-4,-29,8,3);c.fillStyle='#fff';c.fillRect(-4,-55,8,5);c.fillRect(-1,-63,3,8);
 }else if(type==='mite'){
  c.fillStyle='#0008';c.beginPath();c.ellipse(0,3,20,6,0,0,Math.PI*2);c.fill();c.fillStyle='#513473';c.fillRect(-17,-23,34,22);c.fillStyle='#b2a1d0';c.fillRect(-12,-34,24,16);c.fillStyle='#ff4e9b';c.fillRect(-8,-28,5,5);c.fillRect(4,-28,5,5);c.fillStyle='#ded1ee';c.fillRect(-7,-20,14,3);c.strokeStyle='#bd91ed';c.lineWidth=2;for(let i=-1;i<=1;i++){c.beginPath();c.moveTo(i*10,-3);c.lineTo(i*17,4);c.stroke()}
 }
 c.restore();}
function drawObjects(t){const objs=rooms[game.room].objects;for(const o of objs){let x=o.x*960,y=o.y*540;let near=Math.hypot(game.x-x,game.y-y)<100;if(o.id==='dot')sprite(x,y,'dot',1);if(o.id==='host')sprite(x,y,'host',1);if(o.id==='mite'&&!game.battle)sprite(x,y+Math.sin(t*3)*3,'mite',1);if(o.id==='console'){rounded(x-35,y-30,70,50,5,'#18243f','#69e7dc');ctx.fillStyle='#66f2e5';ctx.fillRect(x-25,y-21,50,4);text(game.miniWon?'✓':'▶',x,y+5,23,'#f8f2ff');ctx.fillStyle='#3d3658';ctx.fillRect(x-18,y+23,36,8);text('SIGNAL',x,y+47,9,'#a9a0c8','center','DM Mono')}
 if(o.id==='portal'){let pulse=1+Math.sin(t*3)*.06;ctx.save();ctx.translate(x,y-12);ctx.scale(pulse,1);ctx.shadowColor='#ff4e9b';ctx.shadowBlur=near?28:12;ctx.strokeStyle=game.miniWon?'#ff4e9b':'#685d8a';ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(0,0,35,54,0,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#a74a9d22';ctx.fill();ctx.restore();text(game.miniWon?'CHANNEL 9':'LOCKED',x,y+62,9,game.miniWon?'#f7a9cd':'#8c83a5','center','DM Mono')}
 if(o.id==='secret'){ctx.fillStyle='#ffd56a';ctx.globalAlpha=.65+Math.sin(t*5)*.3;ctx.fillText(game.secret?'✦':'✦',x,y-22);ctx.globalAlpha=1;rounded(x-17,y-13,34,28,2,'#342a4c','#554a6e');ctx.fillStyle='#c2a75e';ctx.fillRect(x-7,y-7,14,3);ctx.fillRect(x-3,y-3,6,7);text(game.secret?'OPEN':'?',x,y+29,9,'#ffd56a','center','DM Mono')}
 if(o.id==='crate'){rounded(x-22,y-20,44,40,4,'#3b2c46','#aa7393');ctx.strokeStyle='#d28a98';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-17,y-15);ctx.lineTo(x+17,y+15);ctx.moveTo(x+17,y-15);ctx.lineTo(x-17,y+15);ctx.stroke();text(game.secret?'EMPTY':'✦',x,y+33,10,'#ffd56a','center','DM Mono')}
 if(o.id==='boss'&&!game.bossWon){ctx.save();ctx.globalAlpha=.85+.15*Math.sin(t*4);ctx.shadowColor='#a957ff';ctx.shadowBlur=18;ctx.strokeStyle='#bd6aff';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(x,y-16,40,56,0,0,Math.PI*2);ctx.stroke();ctx.restore();text('UPLINK',x,y+56,9,'#ce9aff','center','DM Mono')}
 if(near&&game.dialog===null&&!ui.battle.style.display.includes('flex')&&game.started){let prompt=o.id==='mite'?'A · CHECK':o.id==='boss'?'A · GO LIVE':'A · INTERACT';rounded(x-42,y-76,84,20,4,'#15112bea','#5c537b');text(prompt,x,y-62,9,'#fff','center','DM Mono')}
 }}
function drawPlayer(){sprite(game.x,game.y,'tenna',1);}
function drawVignette(){const g=ctx.createRadialGradient(480,260,150,480,260,570);g.addColorStop(0,'#0000');g.addColorStop(1,'#09071988');ctx.fillStyle=g;ctx.fillRect(0,0,960,540);}
function start(){if(game.started)return;game.started=true;ui.story.style.display='none';$('.dpad').style.display='block';$('.interact').style.display='grid';updateHud();openDialogue('TENNA','Good evening, studio audience of twelve! You are all very brave to be here.','start');draw();}
function openDialogue(name,lines,kind='talk'){game.dialog={name,lines:Array.isArray(lines)?lines:[lines],kind};game.dialogIndex=0;ui.speaker.textContent=name;ui.line.textContent=game.dialog.lines[0];ui.choices.innerHTML='';ui.hint.textContent='SPACE / TAP TO CONTINUE';ui.dialog.style.display='block';game.dialogueLock=true;setTimeout(()=>game.dialogueLock=false,180)}
function nextDialogue(){if(!game.dialog)return;if(game.dialogueLock)return;if(game.dialogIndex<game.dialog.lines.length-1){ui.line.textContent=game.dialog.lines[++game.dialogIndex];return}let kind=game.dialog.kind;game.dialog=null;ui.dialog.style.display='none';if(kind==='start'){openDialogue('TENNA',['The ratings are falling because someone is bending the signal. I can feel it in my antenna.','My producer Dot says the console can tune a route through the screen. I say it could use a little more glitter.'], 'tutorial');return}if(kind==='tutorial'){toast('Find Dot and the glowing console.');return}if(kind==='dot'){game.helpedDot=true;return}if(kind==='ending'){finishGame();return}}
function setChoices(items){ui.choices.innerHTML='';ui.hint.textContent='CHOOSE YOUR RESPONSE';items.forEach(it=>{let b=document.createElement('button');b.className='choice';b.textContent=it.label;b.onclick=()=>{ui.choices.innerHTML='';ui.hint.textContent='SPACE / TAP TO CONTINUE';it.run()};ui.choices.appendChild(b)})}
function interact(){if(game.dialog){nextDialogue();return}if(ui.battle.style.display==='flex')return;if(ui.mini.style.display==='flex')return;let objs=rooms[game.room].objects;let o=objs.map(a=>[a,Math.hypot(game.x-a.x*960,game.y-a.y*540)]).filter(a=>a[1]<105).sort((a,b)=>a[1]-b[1])[0]?.[0];if(!o){toast('Nothing here but an unpaid studio tab.');return}
 switch(o.id){case'dot':openDialogue('DOT · ASSISTANT PRODUCER',game.helpedDot?['Already gave you the rundown, boss. Try the console.','Also, there is a suspiciously sparkly crate by the curtain. Not that I care.']:["Boss! The channel's slipping. Viewers want a spectacle, but the signal is... weird.",'Play the jingle on that console to tune the uplink. Then the portal should open.','And if you meet anything hostile, try talking first. Our violence budget got cut.'],'dot');setChoices([{label:'“You’re doing great, Dot.”',run:()=>{game.viewers+=2;updateHud();openDialogue('DOT','...Thanks. I made you a fresh cue card. It just says “breathe.”','dot')}},{label:'“Ratings are all that matters!”',run:()=>{game.viewers=Math.max(0,game.viewers-1);updateHud();openDialogue('DOT','That is... not what I hoped you would say.','dot')}}]);break;
 case'console':if(game.miniWon){openDialogue('CONSOLE','The channel is tuned. The button now says “DO NOT PRESS” in a very inviting font.','console');}else startMini();break;
 case'portal':if(!game.miniWon){openDialogue('PORTAL','A fuzzy screen-door. The console is still searching for a signal.','talk')}else enterChannel();break;
 case'secret':if(!game.secret){game.secret=true;game.stars++;game.viewers+=3;updateHud();openDialogue('???','Inside the crate: one golden star and a note in your own handwriting. “DON’T LET THEM CUT TO BLACK.” You do not remember writing it.','secret')}else openDialogue('TENNA','A prop crate. It smells like old applause.','talk');break;
 case'host':openDialogue('VEE · FORMER GAME-SHOW HOST',['Welcome to the graveyard! I used to host “Wheel of Mild Consequences.”','The director stole my laugh track. Now the silence follows me home.','If you find them, tell them... never mind. I am done asking.'],'host');setChoices([{label:'“I’ll get it back.”',run:()=>{game.viewers+=1;updateHud();openDialogue('VEE','Then take this. The boss hates a sincere compliment.','talk')}},{label:'“That sounds rough.”',run:()=>openDialogue('VEE','It is. I still practice my intro in the mirror.','talk')}]);break;
 case'mite':startBattle(false);break;
 case'crate':if(!game.secret){game.secret=true;game.stars++;updateHud();openDialogue('TENNA','A shiny star hidden beneath the busted game-show podium!','talk')}else openDialogue('TENNA','Just splinters and a deeply judgmental dust bunny.','talk');break;
 case'boss':if(!game.bossWon)startBattle(true);else openDialogue('TENNA','The uplink is quiet now. Too quiet.','talk');break;
 }}
function enterChannel(){game.room='channel';game.x=115;game.y=420;$('#location').textContent=rooms.channel.label;game.roomVisited=true;game.viewers+=2;updateHud();toast('CHANNEL 9 · YOU ARE LIVE');openDialogue('TENNA','Welcome to the Game-Show Graveyard! The applause track is... playing backwards.','talk')}
function returnStudio(){game.room='studio';game.x=855;game.y=410;$('#location').textContent=rooms.studio.label;toast('BACK TO STUDIO ZERO');}
function startMini(){ui.mini.style.display='flex';$('#miniStart').textContent='START THE JINGLE';$('#miniStatus').textContent='Ready when you are, host.';$('#miniBoard').innerHTML='';for(let i=0;i<4;i++){let b=document.createElement('button');b.className='tile';b.textContent=['♫','★','●','▣'][i];b.dataset.i=i;b.onclick=()=>miniTap(i);$('#miniBoard').appendChild(b)}game.miniSequence=[];game.miniInput=[];game.miniBusy=false}
function miniStart(){game.miniSequence=[Math.floor(Math.random()*4),Math.floor(Math.random()*4),Math.floor(Math.random()*4)];game.miniInput=[];game.miniBusy=true;$('#miniStart').disabled=true;$('#miniStatus').textContent='Watch the lights...';let i=0;const flash=()=>{if(i>=game.miniSequence.length){game.miniBusy=false;$('#miniStart').disabled=false;$('#miniStatus').textContent='Your turn! Repeat the jingle.';return}let id=game.miniSequence[i++];let tile=$$('.tile')[id];tile.classList.add('lit');setTimeout(()=>tile.classList.remove('lit'),380);setTimeout(flash,650)};setTimeout(flash,450)}
function miniTap(i){if(game.miniBusy||!game.miniSequence.length)return;let tile=$$('.tile')[i];tile.classList.add('lit');setTimeout(()=>tile.classList.remove('lit'),170);game.miniInput.push(i);let n=game.miniInput.length;if(game.miniInput[n-1]!==game.miniSequence[n-1]){$('#miniStatus').textContent='Wrong note! The TV made a sad trombone noise.';game.miniSequence=[];setTimeout(()=>{if(!game.miniWon){$('#miniStatus').textContent='Try again. The jingle believes in you.';$('#miniStart').disabled=false}},900);return}if(n===game.miniSequence.length){game.miniWon=true;game.viewers+=5;updateHud();$('#miniStatus').textContent='Perfect pitch! Uplink tuned. +5 viewers';$('#miniStart').textContent='SIGNAL LOCKED';$('#miniStart').disabled=true;setTimeout(()=>{ui.mini.style.display='none';openDialogue('CONSOLE',['Signal locked! We have a picture.','Wait. There is a face in the static. It is smiling at you.'],'talk');toast('NEW ROUTE: CHANNEL 9')},1200)}}
function startBattle(boss){game.battle={boss,enemy:boss?'THE DIRECTOR':'STATIC MITE',mood:boss?100:100,hp:boss?100:100,acts:0};game.turn=1;game.defending=false;ui.battle.style.display='flex';$('#enemyTitle').textContent=game.battle.enemy;$('#enemyHpName').textContent=boss?'SIGNAL':'MOOD';$('#enemySprite').textContent=boss?'📡':'◉';$('#enemyLabel').textContent=boss?'???: “YOU’RE OFF SCRIPT.”':'STATIC MITE · FEELS UNSEEN';$('#bossBeam').style.display=boss?'block':'none';$('#battleLog').textContent=boss?'A voice from the uplink cuts in. “We need a better ending.”':'A little blip of static wants a close-up.';battleHud()}
function battleHud(){let b=game.battle;if(!b)return;$('#turnText').textContent=game.turn;$('#hpText').textContent=`${game.hp} / ${game.maxhp}`;$('#hpBarText').textContent=`${game.hp}/${game.maxhp}`;$('#playerBar').style.width=`${100*game.hp/game.maxhp}%`;$('#enemyBarText').textContent=`${Math.max(0,b.mood)}%`;$('#enemyBar').style.width=`${Math.max(0,b.mood)}%`;$$('.battleactions .spare')[0].classList.toggle('disabled',b.mood>35)}
function battleAction(action){let b=game.battle;if(!b)return;if(action==='act'){if(b.boss){b.acts++;b.mood=Math.max(0,b.mood-28);$('#battleLog').textContent=b.acts===1?'You ask who is watching the show. The Director pauses. “No one watches the credits.”':b.acts===2?'You say the audience can tell when someone is lonely. The uplink flickers.':'You thank them for keeping the signal alive. The mask slips.';if(b.acts>=3)$('#battleLog').textContent='The Director is listening. Their signal is losing its grip.';}else{b.mood=Math.max(0,b.mood-40);$('#battleLog').textContent='You ask the mite what it wants. It makes a tiny sound like a dial-up modem.'}enemyTurn();return}
 if(action==='attack'){startTiming();return}
 if(action==='defend'){game.defending=true;game.hp=Math.min(game.maxhp,game.hp+3);$('#battleLog').textContent='You take a breath and hold your cue card up like a shield. +3 HP';battleHud();enemyTurn();return}
 if(action==='spare'){if(b.mood>35){$('#battleLog').textContent='Not yet. It needs to feel heard first.';return}endBattle(true)} }
function startTiming(){ui.timing.style.display='flex';game.attackTimer=0;game.attackPos=0;game.attackDir=1;let tick=()=>{if(ui.timing.style.display!=='flex')return;game.attackPos+=game.attackDir*1.25;if(game.attackPos>96||game.attackPos<1)game.attackDir*=-1;$('#needle').style.left=game.attackPos+'%';raf=requestAnimationFrame(tick)};tick()}
function resolveAttack(){if(ui.timing.style.display!=='flex')return;ui.timing.style.display='none';let pos=game.attackPos;let b=game.battle;let hit=pos>67&&pos<83;if(hit){b.mood=Math.max(0,b.mood-(b.boss?19:25));$('#battleLog').textContent='A perfectly timed dramatic bonk. The audience gasps—then claps.';game.viewers+=1;updateHud()}else{$('#battleLog').textContent='You miss and hit the commercial break button. The jingle is catchy, at least.'}battleHud();enemyTurn()}
